command:
if ([...game.combats].filter(combat => combat.isActive).length !== 0) {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">Le sort n'est pas utilisable en combat</h3>`
    });
} else if (!game.user.character.effects.filter(e => e.label === 'Dégainer')?.length) {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">Vous devez avoir dégainer</h3>`
    });
} else {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: darkgreen;">Vous rengainez et remettez votre main dans la bibliothèque</h3>`
    });
    game.user.character.deleteEmbeddedDocuments("ActiveEffect", game.user.character.effects.filter(e => e.label === 'Dégainer').map(e => e.id));
    const deck = game.cards.filter(cards => cards.ownership[game.userId] === 3 && cards.type === 'deck')[0];
    deck.recall();
    foundry.audio.AudioHelper.play({
        src: "modules/fq-card-engine/sounds/passive_spells/sheathe.mp3",
        volume: 0.4,
        autoplay: true,
        loop: false
    }, true);
}
